#include "auto_animation/rigging/AutoRig.hpp"
#include <iostream>
int main(){using namespace auto_animation::anatomy;using namespace auto_animation::rigging;int f=0;auto e=[&](bool v,const char*m){if(!v){std::cerr<<"FAIL: "<<m<<'\n';++f;}};MarkerSet m;m.profile="Humanoid";m.add_or_replace({MarkerType::Root,"",{0,0,0},{},{},-1,1,true});m.add_or_replace({MarkerType::Pelvis,"",{0,1,0},{},{},-1,1,true});m.add_or_replace({MarkerType::Spine,"",{0,2,0},{},{},-1,1,true});m.add_or_replace({MarkerType::Chest,"",{0,3,0},{},{},-1,1,true});m.add_or_replace({MarkerType::Neck,"",{0,4,0},{},{},-1,1,true});m.add_or_replace({MarkerType::Head,"",{0,5,0},{},{},-1,1,true});m.add_or_replace({MarkerType::ShoulderLeft, "",{-1,3,0},{},{},-1,1,false});m.add_or_replace({MarkerType::ElbowLeft,"",{-2,3,0},{},{},-1,1,false});m.add_or_replace({MarkerType::WristLeft,"",{-3,3,0},{},{},-1,1,false});m.add_or_replace({MarkerType::HandLeft,"",{-4,3,0},{},{},-1,1,false});m.add_or_replace({MarkerType::WingRootLeft,"",{0,3,1},{},{},-1,1,false});m.add_or_replace({MarkerType::WingTipLeft,"",{-2,3,2},{},{},-1,1,false});auto r=build_rig_from_markers(m);e(r.valid(),"marker-driven rig validates");e(r.skeleton.find_bone("Pelvis")==1,"pelvis created with stable parent order");e(r.skeleton.bones[1].parent_index==0,"pelvis attaches to root");e(r.skeleton.bones[r.skeleton.find_bone("Elbow_L")].parent_index==r.skeleton.find_bone("Shoulder_L"),"arm hierarchy follows markers");e(r.skeleton.find_bone("WingTip_L")>=0,"wing markers create non-humanoid extension");e(r.skeleton.bones[r.skeleton.find_bone("Shoulder_L")].bind_local.translation.x==-1.0f,"bind translation is parent-relative");return f;}
